import React, { useEffect, useState } from "react";
import axios from "axios";

export default function AdminDashboard() {
  const [data, setData] = useState([]);

  useEffect(() => {
    const fetchAdmissions = async () => {
      const token = localStorage.getItem("token");
      const res = await axios.get("http://localhost:5000/api/admin/admissions", {
        headers: { Authorization: `Bearer ${token}` }
      });
      setData(res.data);
    };
    fetchAdmissions();
  }, []);

  return (
    <div>
      <h2>Admissions List</h2>
      <table border="1">
        <thead>
          <tr>
            <th>Admission No</th>
            <th>Student Name</th>
            <th>Phone</th>
            <th>Photo</th>
            <th>View</th>
          </tr>
        </thead>
        <tbody>
          {data.map((a) => (
            <tr key={a._id}>
              <td>{a.admissionNo}</td>
              <td>{a.studentName}</td>
              <td>{a.phone}</td>
              <td><img src={`http://localhost:5000${a.photo}`} alt="pic" width="60" /></td>
              <td><a href={`/admin/admission/${a._id}`} target="_blank">View</a></td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
